package com.zerointerrupt.clicker.shizuku

import android.content.ContentProvider
import android.content.ContentValues
import android.database.Cursor
import android.net.Uri
import android.os.Binder
import android.os.Bundle
import android.util.Log

/**
 * Lightweight handshake ContentProvider that receives the live [ITouchMuxService] Binder
 * from the UID 0 [RootMuxServerMain] daemon process.
 *
 * Security:
 * 1. Strictly rejects any caller whose UID != 0 (Process.ROOT_UID).
 * 2. Requires a matching one-time cryptographically random session token generated by [ShizukuController].
 * 3. Returns a client death-sentinel Binder so the Root daemon exits immediately if the app dies.
 */
class RootBinderProvider : ContentProvider() {

    override fun onCreate(): Boolean = true

    override fun call(method: String, arg: String?, extras: Bundle?): Bundle? {
        if (method != METHOD_REGISTER_ROOT_SERVICE) return null

        val callingUid = Binder.getCallingUid()
        if (callingUid != 0) {
            Log.w(TAG, "Rejected RootBinderProvider call from non-root uid=$callingUid")
            return null
        }

        val token = arg?.trim().orEmpty()
        val serviceBinder = extras?.getBinder(EXTRA_SERVICE_BINDER)
        if (token.isEmpty() || serviceBinder == null) {
            Log.w(TAG, "Rejected RootBinderProvider call with missing token or binder")
            return null
        }

        val clientToken = ShizukuController.onRootServiceBinderReceived(token, serviceBinder)
            ?: return null

        return Bundle().apply {
            putBinder(EXTRA_CLIENT_TOKEN, clientToken)
        }
    }

    override fun query(
        uri: Uri,
        projection: Array<out String>?,
        selection: String?,
        selectionArgs: Array<out String>?,
        sortOrder: String?
    ): Cursor? = null

    override fun getType(uri: Uri): String? = null

    override fun insert(uri: Uri, values: ContentValues?): Uri? = null

    override fun delete(uri: Uri, selection: String?, selectionArgs: Array<out String>?): Int = 0

    override fun update(
        uri: Uri,
        values: ContentValues?,
        selection: String?,
        selectionArgs: Array<out String>?
    ): Int = 0

    companion object {
        private const val TAG = "RootBinderProvider"
        const val AUTHORITY_SUFFIX = ".rootbinder"
        const val METHOD_REGISTER_ROOT_SERVICE = "register_root_service"
        const val EXTRA_SERVICE_BINDER = "service_binder"
        const val EXTRA_CLIENT_TOKEN = "client_token"

        fun authorityFor(packageName: String): String = "$packageName$AUTHORITY_SUFFIX"
    }
}
